"""Download UEA/UCR datasets (.ts files) into the shared data cache.

Checks REPRO_DATA_CACHE first, then a project-local cache.  Only the datasets
needed for the target claim (and its cheap sibling) are downloaded.
"""
from __future__ import annotations

import io
import os
import sys
import zipfile

import requests

DEFAULT_DATASET = "GunPointOldVersusYoung"


def urls(dataset: str):
    return [
        f"https://timeseriesclassification.com/aeon-toolkit/{dataset}.zip",
        f"https://www.timeseriesclassification.com/aeon-toolkit/{dataset}.zip",
    ]


def cache_dir() -> str:
    root = os.environ.get("REPRO_DATA_CACHE")
    d = os.path.join(root, "uea_ucr") if root else os.path.join("data", "cache", "uea_ucr")
    os.makedirs(d, exist_ok=True)
    return d


def have_files(d: str, dataset: str) -> bool:
    return all(
        os.path.isfile(os.path.join(d, f"{dataset}_{s}.ts"))
        and os.path.getsize(os.path.join(d, f"{dataset}_{s}.ts")) > 0
        for s in ("TRAIN", "TEST")
    )


def fetch(dataset: str = DEFAULT_DATASET, verbose: bool = True) -> str:
    """Return a directory containing <dataset>_TRAIN.ts / <dataset>_TEST.ts."""
    d = cache_dir()
    files = [f"{dataset}_{s}.ts" for s in ("TRAIN", "TEST")]
    if have_files(d, dataset):
        if verbose:
            print(f"[download] {dataset}: using cache {d}")
        return d

    last_err = None
    for url in urls(dataset):
        try:
            if verbose:
                print(f"[download] {dataset}: GET {url}")
            r = requests.get(url, timeout=180)
            r.raise_for_status()
            zf = zipfile.ZipFile(io.BytesIO(r.content))
            for member in zf.namelist():
                base = os.path.basename(member)
                if base in files:
                    with open(os.path.join(d, base), "wb") as fh:
                        fh.write(zf.read(member))
            if have_files(d, dataset):
                return d
            last_err = RuntimeError(f"zip from {url} lacks {files}")
        except Exception as e:  # noqa: BLE001
            last_err = e
            if verbose:
                print(f"[download] {dataset}: failed ({e})")
    raise RuntimeError(f"could not obtain {dataset}: {last_err}")


if __name__ == "__main__":
    name = sys.argv[1] if len(sys.argv) > 1 else DEFAULT_DATASET
    p = fetch(name)
    print(p)
    for s in ("TRAIN", "TEST"):
        fp = os.path.join(p, f"{name}_{s}.ts")
        print(os.path.basename(fp), os.path.getsize(fp), "bytes")

